-- RightAware — Rights Protection Agencies Directory import
-- Generated from content/organizations.js (36 records: 18 Nigeria + 18 international).
-- Additive and idempotent: safe to run more than once.
--   1) Adds 13 nullable columns (nothing dropped, nothing retyped).
--   2) Inserts 36 rows with ON CONFLICT (id) DO NOTHING — an existing row is
--      never updated and no row is ever deleted.
-- Every record lands as verification_status = 'unverified' (the schema default),
-- so it stays OUT of the public read policy (verified-only) and INSIDE the admin
-- Applications queue for normal review — this import never approves or verifies
-- anything and fires no notification triggers.
-- Contacts are exactly as published in the source directory (research date
-- 2026-10-04); verification_source stays NULL because RightAware has not
-- independently confirmed them.
-- Run in the Supabase SQL editor AFTER schema.sql.

-- ============ 1. new nullable columns ============
alter table organizations
  add column if not exists acronym text,
  add column if not exists country text,
  add column if not exists state text,
  add column if not exists city text,
  add column if not exists org_type text,
  add column if not exists rights_areas text[] default '{}',
  add column if not exists who_they_help text,
  add column if not exists coverage_area text,
  add column if not exists directory_url text,
  add column if not exists keywords text,
  add column if not exists source_url text,
  add column if not exists import_source text,
  add column if not exists last_verified_at date;

comment on column organizations.org_type is 'Organisation type from the directory taxonomy (e.g. Legal Aid (free legal assistance)).';
comment on column organizations.rights_areas is 'Rights-focus areas the organisation covers (directory taxonomy).';
comment on column organizations.directory_url is 'Official directory/contact page (distinct from the website when both are published).';
comment on column organizations.import_source is 'Source collection this record was imported from.';
comment on column organizations.source_url is 'Official page the record details were taken from.';
comment on column organizations.last_verified_at is 'Research date of the SOURCE directory (2026-10-04) — not a RightAware verification date.';

-- ============ 2. 36 directory records ============
on conflict (id) do nothing;
